import React from "react";
import { useFormik } from "formik";
import * as Yup from 'yup';

const input = {
    name: '',
    email: '',
    no: '',
    add: '',
    city: '',
    gender: ''
};

const validate = Yup.object({
    name: Yup.string().min(2).max(100).required('Please enter your full name'),
    email: Yup.string().email('Enter a valid email').required('Please enter your email')
});

function Form() {
    const { values, errors, touched, handleBlur, handleChange, handleSubmit } = useFormik({
        initialValues: input,
        validationSchema: validate,
        onSubmit: async (values) => {
            try {
                const res = await fetch('http://localhost:7000/register', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(values)
                });

                const data = await res.json();
                console.log(data);

                if (res.ok) {
                    alert('registered successfully');
                } else {
                    alert('registration failed');
                }
            } catch (err) {
                console.log(err);
                alert('server error');
            }
        }
    });

    return (
        <div className="form-page">
            <div className="student-form">
                <div className="form-header">
                    <span className="eyebrow">Admission Portal</span>
                    <h1>Student Form</h1>
                </div>

                <form className="student-form__content" onSubmit={handleSubmit}>
                    <div className="form-grid">
                        <div className="form-field">
                            <label htmlFor="name">Student Name</label>
                            <input type="text" id="name" name="name" value={values.name} onChange={handleChange} onBlur={handleBlur} />
                            {(errors.name && touched.name) && <span className="error-text">{errors.name}</span>}
                        </div>

                        <div className="form-field">
                            <label htmlFor="email">Email</label>
                            <input type="text" id="email" name="email" value={values.email} onChange={handleChange} onBlur={handleBlur} />
                            {(errors.email && touched.email) && <span className="error-text">{errors.email}</span>}
                        </div>

                        <div className="form-field">
                            <label htmlFor="no">Phone Number</label>
                            <input type="text" id="no" name="no" value={values.no} onChange={handleChange} onBlur={handleBlur} />
                            {(errors.no && touched.no) && <span className="error-text">{errors.no}</span>}
                        </div>

                        <div className="form-field">
                            <label htmlFor="add">Address</label>
                            <input type="text" id="add" name="add" value={values.add} onChange={handleChange} onBlur={handleBlur} />
                            {(errors.add && touched.add) && <span className="error-text">{errors.add}</span>}
                        </div>

                        <div className="form-field full-width">
                            <label htmlFor="inputState">City</label>
                            <select id="inputState" className="form-select" name="city" value={values.city} onChange={handleChange} onBlur={handleBlur}>
                                <option value="">Select City</option>
                                <option value="Surat">Surat</option>
                                <option value="Vapi">Vapi</option>
                                <option value="Valsad">Valsad</option>
                                <option value="Navsari">Navsari</option>
                                <option value="Baroda">Baroda</option>
                            </select>
                        </div>

                        <div className="full-width">
                            <label className="gender-label">Gender</label>
                            <div className="gender-options">
                                <label className="radio-card">
                                    <input type="radio" name="gender" value="male" onChange={handleChange} onBlur={handleBlur} />
                                    <span>Male</span>
                                </label>
                                <label className="radio-card">
                                    <input type="radio" name="gender" value="female" onChange={handleChange} onBlur={handleBlur} />
                                    <span>Female</span>
                                </label>
                            </div>
                        </div>
                    </div>

                    <button type="submit" className="submit-btn">Submit</button>
                </form>
            </div>
        </div>
    );
}

export default Form;
